import{_ as e,c as r,o as i,ah as n}from"./chunks/framework.Dnh4IO1K.js";const b=JSON.parse('{"title":"29、【坎】 坎下坎上","description":"溫公易說 - 29、【坎】 坎下坎上","frontmatter":{"title":"29、【坎】 坎下坎上","description":"溫公易說 - 29、【坎】 坎下坎上"},"headers":[],"relativePath":"classics/wengong/030.md","filePath":"classics/wengong/030.md"}'),l={name:"classics/wengong/030.md"};function t(h,a,s,o,d,c){return i(),r("div",null,[...a[0]||(a[0]=[n('<h1 id="_29、【坎】-坎下坎上" tabindex="-1">29、【坎】 坎下坎上 <a class="header-anchor" href="#_29、【坎】-坎下坎上" aria-label="Permalink to “29、【坎】 坎下坎上”">​</a></h1><h3 id="彖曰-習坎-重險也。水流而不盈-行險而不失其信。維心亨-乃以剛中也。行有尚-往有功也。天險不可升也-地險山川丘陵也。王公設險以守其國-險之時用大矣哉。" tabindex="-1">彖曰：習坎，重險也。水流而不盈，行險而不失其信。維心亨，乃以剛中也。行有尚，往有功也。天險不可升也，地險山川丘陵也。王公設險以守其國，險之時用大矣哉。 <a class="header-anchor" href="#彖曰-習坎-重險也。水流而不盈-行險而不失其信。維心亨-乃以剛中也。行有尚-往有功也。天險不可升也-地險山川丘陵也。王公設險以守其國-險之時用大矣哉。" aria-label="Permalink to “彖曰：習坎，重險也。水流而不盈，行險而不失其信。維心亨，乃以剛中也。行有尚，往有功也。天險不可升也，地險山川丘陵也。王公設險以守其國，險之時用大矣哉。”">​</a></h3><h3 id="象曰-水洊至-習坎。君子以常德行-習教事。" tabindex="-1">象曰：水洊至，習坎。君子以常德行，習教事。 <a class="header-anchor" href="#象曰-水洊至-習坎。君子以常德行-習教事。" aria-label="Permalink to “象曰：水洊至，習坎。君子以常德行，習教事。”">​</a></h3><p>坎以常德行，習教事何也？水之為德，無有方圓曲直高下夷險，而不失其平者也。故君子以常德行，水之流也，習而不止，以成大川。人之學也，習而不止，以成大賢。故君子以習教事。</p><h3 id="初六-習坎-入於坎窞-兇-象曰-習坎入坎-失道兇也。" tabindex="-1">初六：習坎，入於坎窞，兇 象曰：習坎入坎，失道兇也。 <a class="header-anchor" href="#初六-習坎-入於坎窞-兇-象曰-習坎入坎-失道兇也。" aria-label="Permalink to “初六：習坎，入於坎窞，兇 象曰：習坎入坎，失道兇也。”">​</a></h3><p>初者事之始也，聖人之教人也，禁其始不禁其終，防其始不防其終。故坤之初六曰：履霜堅冰至。震之初九曰：震來虩虩，後笑言啞啞，吉。皆原其始而要終也。夫人之於險也，始皆有恐懼之心焉，及幸而濟也，則狃以為常，至於失身而不自知也。是以聖人於險之初而戒其將來之禍，曰習坎入於坎窞，兇。窞者，坎中之坎也。</p><h3 id="九二-坎有險-求小得-象曰-求小得-未出中也。" tabindex="-1">九二：坎有險，求小得 象曰：求小得，未出中也。 <a class="header-anchor" href="#九二-坎有險-求小得-象曰-求小得-未出中也。" aria-label="Permalink to “九二：坎有險，求小得 象曰：求小得，未出中也。”">​</a></h3><h3 id="六三-來之坎坎-險且枕-入於坎窞-勿用-象曰-來之坎坎-終無功也。" tabindex="-1">六三：來之坎坎，險且枕，入於坎窞，勿用 象曰：來之坎坎，終無功也。 <a class="header-anchor" href="#六三-來之坎坎-險且枕-入於坎窞-勿用-象曰-來之坎坎-終無功也。" aria-label="Permalink to “六三：來之坎坎，險且枕，入於坎窞，勿用 象曰：來之坎坎，終無功也。”">​</a></h3><h3 id="六四-樽酒簋貳-用缶-納約自牖-終無咎-象曰-樽酒簋貳-剛柔際也。" tabindex="-1">六四：樽酒簋貳，用缶，納約自牖，終無咎 象曰：樽酒簋貳，剛柔際也。 <a class="header-anchor" href="#六四-樽酒簋貳-用缶-納約自牖-終無咎-象曰-樽酒簋貳-剛柔際也。" aria-label="Permalink to “六四：樽酒簋貳，用缶，納約自牖，終無咎 象曰：樽酒簋貳，剛柔際也。”">​</a></h3><h3 id="九五-坎不盈-祇既平-無咎-象曰-坎不盈-中未大也。" tabindex="-1">九五：坎不盈，祇既平，無咎 象曰：坎不盈，中未大也。 <a class="header-anchor" href="#九五-坎不盈-祇既平-無咎-象曰-坎不盈-中未大也。" aria-label="Permalink to “九五：坎不盈，祇既平，無咎 象曰：坎不盈，中未大也。”">​</a></h3><h3 id="上六-系用徽纆-置於叢棘-三歲不得-兇-象曰-上六失道-兇三歲也。" tabindex="-1">上六：系用徽纆，置於叢棘，三歲不得，兇 象曰：上六失道，兇三歲也。 <a class="header-anchor" href="#上六-系用徽纆-置於叢棘-三歲不得-兇-象曰-上六失道-兇三歲也。" aria-label="Permalink to “上六：系用徽纆，置於叢棘，三歲不得，兇 象曰：上六失道，兇三歲也。”">​</a></h3>',11)])])}const m=e(l,[["render",t]]);export{b as __pageData,m as default};
